function initMobileHeader(){
  const h=document.getElementById('header');
  const top=h&&h.querySelector('.top');
  if(!h||!top||h.querySelector('#mobileMenuToggle')) return;
  const currentPage=document.body.dataset.sitePage||((document.body.dataset.gameSlug)?'game':'home');
  const navActive=p=>currentPage===p?' class="active"':'';
  const btn=document.createElement('button');
  btn.type='button'; btn.id='mobileMenuToggle'; btn.className='mobile-menu-toggle';
  btn.setAttribute('aria-label','Open menu'); btn.setAttribute('aria-expanded','false');
  btn.innerHTML='<span></span><span></span><span></span>';
  top.appendChild(btn);
  const menu=document.createElement('div');
  menu.id='mobileMenu'; menu.className='mobile-menu'; menu.hidden=true;
  menu.innerHTML=`<nav aria-label="Mobile navigation">
    <a${navActive('home')} href="${homePath('#games')}">Home</a>
    <a${navActive('about')} href="${sitePagePath('about')}">About</a>
    <a href="${sitePagePath('guides')}">Guides</a>
    <a${navActive('contact')} href="${sitePagePath('contact')}">Contact</a>
    <a${navActive('disclaimer')} href="${sitePagePath('disclaimer')}">Disclaimer</a>
    <a${navActive('telegram')} href="${sitePagePath('telegram')}">Telegram</a>
  </nav>`;
  h.appendChild(menu);
  const close=()=>{menu.hidden=true;btn.setAttribute('aria-expanded','false');btn.setAttribute('aria-label','Open menu')};
  btn.addEventListener('click',()=>{const open=menu.hidden;menu.hidden=!open;btn.setAttribute('aria-expanded',String(open));btn.setAttribute('aria-label',open?'Close menu':'Open menu')});
  menu.querySelectorAll('a').forEach(a=>a.addEventListener('click',close));
  window.addEventListener('resize',()=>{if(innerWidth>700)close()},{passive:true});
}


