function getDemoPlayers(game,index=0){
 const key=String((game&&game.id)||game&&game.slug||game&&game.name||index);
 let h=0; for(let i=0;i<key.length;i++) h=((h*31)+key.charCodeAt(i))>>>0;
 const value=100000+(h%400001);
 return (value/1000).toFixed(1)+'K';
}
const PLAYER_LIVE_KEY='yono_looters_live_players_v1';
function playerKey(game,index=0){return String((game&&game.id)||game&&game.slug||game&&game.name||index)}
function seededPlayerNumber(game,index=0){
 const key=playerKey(game,index);
 let h=0; for(let i=0;i<key.length;i++) h=((h*31)+key.charCodeAt(i))>>>0;
 return 100000+(h%400001);
}
function getLivePlayerNumber(game,index=0){
 try{
   const raw=localStorage.getItem(PLAYER_LIVE_KEY);
   const state=raw?JSON.parse(raw):{};
   const key=playerKey(game,index);
   if(!state[key]||typeof state[key].value!=='number'){
     state[key]={value:seededPlayerNumber(game,index),updatedAt:Date.now()};
     localStorage.setItem(PLAYER_LIVE_KEY,JSON.stringify(state));
   }
   return Math.max(100000,Math.min(500000,Math.round(state[key].value)));
 }catch(e){return seededPlayerNumber(game,index)}
}
function formatPlayers(n){return (n/1000).toFixed(1)+'K'}
function startLivePlayerCounts(){
 if(window.__yonoLivePlayersStarted)return;
 window.__yonoLivePlayersStarted=true;
 const tick=()=>{
   const nodes=[...document.querySelectorAll('[data-player-key]')];
   if(!nodes.length)return;
   try{
     const raw=localStorage.getItem(PLAYER_LIVE_KEY);
     const state=raw?JSON.parse(raw):{};
     nodes.forEach(node=>{
       const key=node.dataset.playerKey;
       if(!state[key])state[key]={value:100000,updatedAt:Date.now()};
       const current=Math.round(Number(state[key].value)||100000);
       const change=1+Math.floor(Math.random()*12);
       state[key].value=Math.min(500000,current+change);
       state[key].updatedAt=Date.now();
       node.textContent=formatPlayers(state[key].value)+' players';
       node.classList.remove('count-up'); void node.offsetWidth; node.classList.add('count-up');
     });
     localStorage.setItem(PLAYER_LIVE_KEY,JSON.stringify(state));
   }catch(e){}
 };
 setInterval(tick,6000);
}
